class Component extends DCLogic {
  state = {};
  subTimer = null;
  subInit() { return;
    const st = this.state.subState || {};
    if (localStorage.getItem('tcf_sub_dismissed') || localStorage.getItem('tcf_sub_done')) return;
    this.subTimer = setTimeout(() => this.setState({ subOpen: true }), 30000);
  }
  subVals() {
    return {
      subOpen: !!this.state.subOpen, subDone: !!this.state.subDone, subPending: !this.state.subDone, subEmail: this.state.subEmail || '',
      subChange: ev => this.setState({ subEmail: ev.target.value }),
      subClose: () => { localStorage.setItem('tcf_sub_dismissed', String(Date.now())); this.setState({ subOpen: false }); },
      subSubmit: ev => { ev.preventDefault(); localStorage.setItem('tcf_sub_done', '1'); this.setState({ subDone: true }); setTimeout(() => this.setState({ subOpen: false }), 2500); }
    };
  }
  componentDidMount() { this.subInit(); }
  componentWillUnmount() { clearTimeout(this.subTimer); }
  renderVals() { return { ...this.subVals() }; }
}
